  """

  # This test is compiled only on macOS (`tests/feature/example.rs`).
  @macos_only MapSet.new([
                {"pbeam-runtime::example",
                 "restores_the_terminal_before_the_result_of_terra_counter_as_interactive_erts"}
              ])

  @purposes ~w(application_end_to_end cli erts_comparison erts_reference host_integration interoperability native_extension pure_logic runtime_integration test_helper)
  @dependencies ~w(build_toolchain epmd erts_peer erts_process erts_process_may_be_conditional filesystem host_commands host_signals native_library network none pbeam_process pbeam_tool pipes pty real_time unknown)

  def inventory, do: parse_inventory(@inventory)

  def parse_inventory(text) do
    text
    |> String.split("\n", trim: true)
    |> Enum.map(fn line ->
      case String.split(line, "|") do
        [binary, name, purpose, dependencies] ->
          if binary == "" or name == "" or String.trim(binary) != binary or
               String.trim(name) != name,
             do: raise("invalid test identity: #{line}")

          purposes = split(purpose)
          deps = split(dependencies)
          validate_labels(purposes, @purposes, line)
          validate_labels(deps, @dependencies, line)

          if "none" in deps and length(deps) != 1,
            do: raise("none cannot have other dependencies: #{line}")

          {{binary, name}, %{purpose: purposes, dependencies: deps}}

        _ ->
          raise "invalid inventory line: #{line}"
      end
    end)
    |> then(fn entries ->
      map = Map.new(entries)
      if map_size(map) != length(entries), do: raise("duplicate test identity in inventory")
      map
    end)
  end

  defp split(""), do: []
  defp split(value), do: String.split(value, ",")

  defp validate_labels(labels, allowed, line) do
    if Enum.any?(labels, &(&1 not in allowed)) or length(Enum.uniq(labels)) != length(labels),
      do: raise("invalid or duplicate facet: #{line}")
  end

  def incomplete?(nil), do: true

  def incomplete?(%{purpose: purpose, dependencies: dependencies}) do
    purpose == [] or dependencies == [] or "unknown" in dependencies
  end

  def run(args) do
    {options, paths, invalid} =
      OptionParser.parse(args,
        strict: [
          strict: :boolean,
          cases: :boolean,
          purpose: :string,
          dependency: :string,
          platform: :string
        ]
      )

    if invalid != [] or length(paths) != 2 do
      raise "usage: elixir scripts/test_classes.exs [--strict] [--cases] [--purpose LABEL] [--dependency LABEL] [--platform linux|macos] <cargo-metadata.json> <nextest-list.json>"
    end

    if options[:purpose] && options[:purpose] not in @purposes,
      do: raise("unknown purpose filter: #{options[:purpose]}")

    if options[:dependency] && options[:dependency] not in @dependencies,
      do: raise("unknown dependency filter: #{options[:dependency]}")

    platform =
      options[:platform] ||
        case :os.type() do
          {:unix, :linux} -> "linux"
          {:unix, :darwin} -> "macos"
          _ -> "other"
        end

    unless platform in ["linux", "macos", "other"], do: raise("unknown platform: #{platform}")

    [metadata_path, list_path] = paths
    metadata = metadata_path |> File.read!() |> :json.decode()
    list = list_path |> File.read!() |> :json.decode()
    known = inventory()

    targets =
      for package <- Map.fetch!(metadata, "packages"),
          target <- Map.fetch!(package, "targets"),
          "test" in Map.fetch!(target, "kind"),
          String.contains?(Map.fetch!(target, "src_path"), "/tests/feature/"),
          into: MapSet.new() do
        package["name"] <> "::" <> target["name"]
      end

    if MapSet.size(targets) == 0, do: raise("metadata has no feature test targets")
    suites = Map.fetch!(list, "rust-suites")
    listed = MapSet.new(Map.keys(suites))
    missing_targets = MapSet.difference(targets, listed)

    if MapSet.size(missing_targets) != 0,
      do: raise("nextest list omits feature targets: #{inspect(Enum.sort(missing_targets))}")

    cases =
      for {id, suite} <- suites,
          MapSet.member?(targets, id),
          {name, info} <- Map.fetch!(suite, "testcases"),
          into: %{} do
        status =
          get_in(info, ["filter-match", "status"]) ||
            raise("missing filter status: #{id} #{name}")

        unless status in ["matches", "mismatch"], do: raise("unknown filter status #{status}")
        {{id, name}, %{selected: status == "matches"}}
      end

    if map_size(cases) == 0, do: raise("nextest list has no feature test cases")
    unrecorded = Map.keys(cases) -- Map.keys(known)
    absent = Map.keys(known) -- Map.keys(cases)
    expected_absent = if platform == "linux", do: @macos_only, else: MapSet.new()
    unexpected_absent = Enum.reject(absent, &MapSet.member?(expected_absent, &1))

    for {id, name} <- Enum.sort(unrecorded), do: IO.puts(:stderr, "unrecorded: #{id} #{name}")

    for {id, name} <- Enum.sort(absent) do
      kind =
        if MapSet.member?(expected_absent, {id, name}),
          do: "platform excluded",
          else: "not listed on this platform"

      IO.puts(:stderr, "#{kind}: #{id} #{name}")
    end

    incomplete = Enum.filter(cases, fn {key, _} -> incomplete?(known[key]) end)

    selected = Enum.count(cases, fn {_, %{selected: selected}} -> selected end)

    IO.puts(
      "Feature targets: #{MapSet.size(targets)}; cases: #{map_size(cases)}; selected: #{selected}"
    )

    IO.puts(
      "Cases with unknown purpose or dependencies: #{length(incomplete)}; unrecorded: #{length(unrecorded)}; not listed: #{length(absent)}"
    )

    for facet <- [:purpose, :dependencies] do
      counts =
        for {key, _} <- cases,
            label <- get_in(known, [key, facet]) || [],
            reduce: %{} do
          counts -> Map.update(counts, label, 1, &(&1 + 1))
        end

      IO.puts(
        "#{facet}: " <>
          Enum.map_join(Enum.sort(counts), ", ", fn {label, count} -> "#{label}=#{count}" end)
      )
    end

    matching =
      Enum.filter(cases, fn {key, _} ->
        entry = Map.get(known, key, %{purpose: [], dependencies: []})

        (is_nil(options[:purpose]) or options[:purpose] in entry.purpose) and
          (is_nil(options[:dependency]) or options[:dependency] in entry.dependencies)
      end)

    if options[:purpose] || options[:dependency] do
      IO.puts("Matching both requested facets: #{length(matching)}")
    end

    if options[:cases] do
      for {{id, name} = key, info} <- Enum.sort(matching) do
        entry = Map.get(known, key, %{purpose: [], dependencies: ["unknown"]})
        purpose = if entry.purpose == [], do: "unknown", else: Enum.join(entry.purpose, ",")

        deps =
          if entry.dependencies == [], do: "unknown", else: Enum.join(entry.dependencies, ",")

        IO.puts(
          "#{id} #{name}: purpose=#{purpose}; dependencies=#{deps}; selected=#{info.selected}"
        )
      end
    end

    if unrecorded != [] or
         (options[:strict] == true and (incomplete != [] or unexpected_absent != [])),
       do: System.halt(1)
  end
end

TestClasses.run(System.argv())
